import com.bridger.momentum.*;
import java.nio.file.*;

public final class ReplayVideoPresentationRegression {
    private static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
    private static final class Canvas implements UiCanvas{int held;String text="";public void rect(int x,int y,int w,int h,int color){if(color==0xE0275665)held++;}public void text(String s,int x,int y,int color){text+=s+"\n";}public int width(String s){return s.length()*6;}public void textScaled(String s,int x,int y,int color,float scale){text(s,x,y,color);}}
    public static void main(String[] args)throws Exception{
        ReplayVideoOptions options=ReplayVideoOptions.defaults();check(options.inputs&&options.title&&options.cleanHud&&options.height==1080&&!options.metrics,"Default export presentation is missing keystrokes or clean 1080p output");Path file=Files.createTempDirectory("video-options-").resolve("settings.properties");new ReplayVideoOptions(120,720,1,false,true,true,false).save(file);ReplayVideoOptions read=ReplayVideoOptions.load(file);check(read.fps==120&&read.camera==1&&read.metrics&&!read.inputs&&!read.cleanHud,"Export preferences were not remembered");Files.write(file,"fps=999\n".getBytes("UTF-8"));check(ReplayVideoOptions.load(file).fps==60,"Bad preferences did not fall back safely");
        ReplayData.TickStats stats=new ReplayData.TickStats(1|4|16|256,0,0,0,1,0,7,12,0,.1,.2,.3);ReplayData.Frame frame=new ReplayData.Frame(1,65,2,0,0,0,0,false,true,0,0,0,24,0,stats);BridgeConfig.showReplayInputs=false;Canvas canvas=new Canvas();ReplayVideoOverlay.paint(canvas,640,360,frame,"Practice bridge",1,3.85,options);check(canvas.held==4,"Export lost recorded keystrokes when the normal input HUD was disabled");check(canvas.text.contains("CPS 7 / 12")&&canvas.text.contains("1.00 / 3.85s"),"CPS/title timing missing");check(!canvas.text.contains("Paused")&&!canvas.text.contains("Sticks:"),"Playback controls leaked into exported HUD");Canvas hidden=new Canvas();ReplayVideoOverlay.paint(hidden,640,360,frame,"Practice bridge",1,3.85,new ReplayVideoOptions(60,1080,0,false,false,false,true));check(hidden.held==0&&hidden.text.isEmpty(),"Explicit export overlay toggles were ignored");Canvas legacy=new Canvas();ReplayVideoOverlay.paint(legacy,320,180,new ReplayData.Frame(1,2,3),"Old bridge",0,1,options);check(legacy.text.contains("No input data"),"Missing recording data was replaced by spectator inputs");
        ReplayData.Frame first=new ReplayData.Frame(0,65,0),last=new ReplayData.Frame(0,65,30);double[] a=ReplayVideoCamera.follow(frame,first,last);check(a[0]<frame.x&&a[2]<frame.z&&a[1]>frame.y,"Follow camera is not above/beside/behind the actor");for(double v:a)check(Double.isFinite(v),"Follow camera has an invalid pose");
        check(IslandAnchorPolicy.inLane(0,40,0,30,10),"Finish observer was mistaken for another lane");check(!IslandAnchorPolicy.inLane(0,500,0,30,10),"Another bridge far along the same axis was accepted");check(!IslandAnchorPolicy.inLane(32,0,0,30,10),"Adjacent lane was accepted as the original start");check(IslandAnchorPolicy.inLane(-40,0,-30,0,10)&&!IslandAnchorPolicy.inLane(0,32,-30,0,10),"Negative-axis lane selection is wrong");
        check(options.hotbar&&options.ending,"Block hotbar or final time was not enabled by default");Canvas result=new Canvas();ReplayVideoOverlay.ending(result,640,360,ReplayVideoItems.time(3.95,5.95));check(result.text.contains("3.950")&&!result.text.contains("5.950"),"End card uses padded video duration instead of saved run time");
        ReplayData.Block firstBlock=new ReplayData.Block(0,64,0,24,2,3,true),secondBlock=new ReplayData.Block(0,64,1,35,14,8,true);ReplayData build=new ReplayData(java.util.Collections.nCopies(10,frame),java.util.Arrays.asList(new ReplayData.Block(9,64,9,1,0,0,false),secondBlock,firstBlock),false);check(ReplayVideoItems.block(build,0)==firstBlock&&ReplayVideoItems.block(build,5)==firstBlock&&ReplayVideoItems.block(build,8)==secondBlock,"Hotbar chose terrain, spectator controls or the wrong construction variant");check(ReplayVideoItems.block(new ReplayData(java.util.Arrays.asList(frame),java.util.Collections.emptyList(),false),0)==null,"Missing block data invented a construction block");
        System.out.println("PASS: independent recorded keystrokes/CPS, clean titles, export preferences, follow framing and lane rejection");
    }
}
